import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup registers the user and returns a working token", async () => {
  const res = await call("POST", "/api/signup", { email: "Grace@example.com", name: "Grace", password: "correct horse" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.equal(user.email, "grace@example.com");
  assert.equal(user.name, "Grace");
  assert.ok(!("passwordHash" in user));
  const me = await call("GET", "/api/me", undefined, token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signup rejects a duplicate email, a bad email, and a short password with 400", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "ada@example.com", name: "Ada", password: "correct horse" })).status, 201);
  for (const body of [
    { email: "ADA@example.com", name: "Ada", password: "correct horse" },
    { email: "not-an-email", name: "X", password: "correct horse" },
    { email: "x@example.com", name: "X", password: "short" },
  ]) {
    const res = await call("POST", "/api/signup", body);
    assert.equal(res.status, 400);
    assert.ok((res.body as { error: string }).error.length > 0);
  }
});

test("signup requires email, name and password", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "a@b.co", password: "correct horse" })).status, 400);
});

